<?php defined('ALTUMCODE') || die();$h='fcc_partner_h';$t='fcc_wl_t';$uid=(int)$this->user->user_id;$token='<input type="hidden" name="token" value="'.$h(\Altum\Csrf::get()).'">';
\Altum\Event::add_content('<link rel="stylesheet" href="'.ASSETS_FULL_URL.'css/fcc-webinar.css?v='.filemtime(ASSETS_PATH.'css/fcc-webinar.css').'"><link rel="stylesheet" href="'.ASSETS_FULL_URL.'css/fcc-webinar-lifecycle.css?v='.filemtime(ASSETS_PATH.'css/fcc-webinar-lifecycle.css').'"><script defer src="'.ASSETS_FULL_URL.'js/fcc-webinar.js?v='.filemtime(ASSETS_PATH.'js/fcc-webinar.js').'"></script>','head'); ?>
<div class="fp-workspace fp-webinar-workspace wl-workspace"><header class="fp-invite-heading"><span class="fp-eyebrow">FOREVER CARD CLUB</span><h1><?= $h($t('guests')) ?></h1><p><?= $h($t('guests_help')) ?></p><div class="fv-actions"><a class="fp-button fp-button-outline" href="<?= url('partner/share?type=webinar') ?>"><?= $h($t('prepare')) ?></a><a class="fp-link" href="<?= url('partner-webinar?view=activity') ?>"><?= $h($t('history')) ?></a></div></header>
<?php if($data->error): ?><p class="fp-message fp-error" role="alert"><?= $h($data->error) ?></p><?php elseif(isset($_GET['saved'])): ?><p class="fp-message" role="status"><?= $h($t('saved')) ?></p><?php endif ?>
<?php if($data->session): ?><section class="fp-panel"><h2><?= $h($data->session['title']) ?></h2><p><?= $h(fcc_webinar_label_time($data->session)) ?></p>
<?php if($data->session['ends_at_utc']<=gmdate('Y-m-d H:i:s')&&fcc_wl_summary($uid,(int)$data->sid)['pending']): ?>
<?php if(empty($data->followup['snoozed'])): ?><form method="post"><?= $token ?><button class="fp-button fp-button-outline" name="lifecycle_action" value="snooze"><?= $h($t('snooze')) ?></button></form><?php else: ?><p><?= $h($t('snoozed')) ?></p><?php endif ?><?php endif ?></section><?php endif ?>
<?php if($data->prepared): $i=$data->prepared;$msg=fcc_wl_message($i,fcc_wl_return_url($i)); ?>
<section class="fp-panel"><h2><?= $h($t('invite_ready')) ?></h2><div data-webinar-followup data-phone="<?= $h(preg_replace('/\D/','',$i['phone'])) ?>"><label for="wl-return-message"><?= $h($t('message')) ?></label><textarea class="form-control" id="wl-return-message" rows="6"><?= $h($msg) ?></textarea><div class="fv-actions"><a class="fp-button" data-followup-whatsapp href="<?= $h('https://wa.me/'.preg_replace('/\D/','',$i['phone']).'?text='.rawurlencode($msg)) ?>" target="_blank" rel="noopener noreferrer"><?= $h($t('whatsapp')) ?></a></div></div><p><?= $h($t('manual_send')) ?></p><form method="post"><?= $token ?><input type="hidden" name="return_id" value="<?= (int)$i['id'] ?>"><button class="fp-button fp-button-outline" name="lifecycle_action" value="sent"><?= $h($t('sent')) ?></button></form></section>
<?php endif ?>
<?php if(!$data->rows): ?><section class="fp-panel"><p><?= $h($t('empty')) ?></p></section><?php endif ?>
<?php foreach($data->rows as $r): $past=$r['ends_at_utc']<=gmdate('Y-m-d H:i:s');$active=$r['status']==='registered'&&$r['session_status']==='scheduled';$s=fcc_partner_one('SELECT * FROM fcc_webinar_sessions WHERE id=?',[(int)$r['session_id']]);$may=fcc_webinar_may_contact_registration($r);$mayInvite=fcc_wl_may_contact($r);$next=fcc_wl_next($uid,$s); ?>
<section class="fp-panel wl-guest" id="registration-<?= (int)$r['id'] ?>"><div class="fp-section-title"><h2><a href="<?= url('partner/contacts?id='.(int)$r['contact_id']) ?>"><?= $h($r['contact_name']) ?></a></h2><span class="fv-badge"><?= $h($t($r['status']==='cancelled'?'cancelled':($past?$r['attendance']:'registered'))) ?></span></div><h3><?= $h($r['title']) ?></h3><p><?= $h(fcc_webinar_label_time($r)) ?></p><p class="fp-muted"><?= $h($r['reminder_opt_in']?($r['email_verified_at']?$t('reminders_on'):$t('verify_pending')):$t('reminders_off')) ?></p>
<?php if($r['needs_review']): ?><p><?= $h($t('review')) ?></p><?php endif ?>
<?php if($past&&$active&&empty($r['archived_at'])): ?><form method="post" class="fp-form"><?= $token ?><input type="hidden" name="lifecycle_action" value="outcome"><input type="hidden" name="registration_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="version" value="<?= (int)$r['outcome_version'] ?>"><label for="wl-attendance-<?= (int)$r['id'] ?>"><?= $h($t('attendance')) ?></label><select id="wl-attendance-<?= (int)$r['id'] ?>" name="attendance"><?php foreach(['unknown','attended','missed'] as $state): ?><option value="<?= $state ?>" <?= $r['attendance']===$state?'selected':'' ?>><?= $h($t($state)) ?></option><?php endforeach ?></select><small><?= $h($t('manual_outcome')) ?></small><?php if($may): ?><label class="fv-check"><input type="checkbox" name="contacted" value="1" <?= $r['contacted_at']?'checked':'' ?>><span><?= $h($t('contacted')) ?></span></label><?php endif ?><button class="fp-button" type="submit"><?= $h($t('save')) ?></button></form><?php endif ?>
<?php if($may&&$active): $msg=fcc_wl_message($r); ?><p class="fp-muted"><?= $h($t('registration_contact')) ?></p><details class="fv-details"><summary><?= $h($t('message')) ?></summary><div data-webinar-followup data-phone="<?= $h(preg_replace('/\D/','',$r['contact_phone'])) ?>"><label class="sr-only" for="wl-message-<?= (int)$r['id'] ?>"><?= $h($t('message')) ?></label><textarea class="form-control" id="wl-message-<?= (int)$r['id'] ?>" rows="5"><?= $h($msg) ?></textarea><div class="fv-actions"><a class="fp-button fp-button-outline" data-followup-whatsapp target="_blank" rel="noopener noreferrer" href="<?= $h('https://wa.me/'.preg_replace('/\D/','',$r['contact_phone']).'?text='.rawurlencode($msg)) ?>"><?= $h($t('whatsapp')) ?></a></div></div><p><?= $h($t('manual_send')) ?></p></details><?php elseif(!$may): ?><p class="fp-muted"><?= $h($t('no_permission')) ?></p><?php endif ?>
<?php if($next&&$mayInvite): ?><form method="post" class="wl-next"><?= $token ?><input type="hidden" name="registration_id" value="<?= (int)$r['id'] ?>"><p><?= $h($t('next')) ?>: <?= $h(fcc_webinar_label_time($next)) ?></p><button class="fp-button fp-button-outline" name="lifecycle_action" value="invite"><?= $h($t('invite_next')) ?></button></form><?php endif ?></section>
<?php endforeach ?>
<nav class="fv-actions" aria-label="<?= $h($t('history')) ?>"><?php $pager='partner-webinar?view=guests'.($data->sid?'&session_id='.$data->sid:'').($data->cid?'&contact_id='.$data->cid:'');if($data->page>0): ?><a class="fp-button fp-button-outline" href="<?= url($pager.'&page='.($data->page-1)) ?>"><?= $h($t('newer')) ?></a><?php endif ?><?php if($data->more): ?><a class="fp-button fp-button-outline" href="<?= url($pager.'&page='.($data->page+1)) ?>"><?= $h($t('older')) ?></a><?php endif ?></nav></div>
